const fs=require('fs'),path=require('path');
const out=path.resolve('evidence/usability-20261023-r1/before');fs.mkdirSync(out,{recursive:true});
function edit(file,fn){const p=path.resolve(file),s=fs.readFileSync(p,'utf8');fs.copyFileSync(p,path.join(out,path.basename(p)));fs.writeFileSync(p,fn(s));}
edit('src/index.html',s=>s.replace(/<button id="quickAutoPlay"[\s\S]*?<button id="quickNames"/,'<button id="quickNames"').replace('<div class="section-label">分类',`<div class="section-label">素材类型</div><nav id="typeShortcuts" aria-label="按素材类型浏览">${[['pr','Pr','Premiere'],['ae','Ae','After Effects'],['ps','Ps','Photoshop'],['audio','♫','音频 / 声音']].map(([key,icon,label])=>`<button class="nav type-shortcut" data-type="${key}" aria-pressed="false"><span class="type-badge type-${key}" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="section-label">分类`).replace('视频播放</button>','播放预览</button>').replace('id="prefAutoPlay">自动播放','id="prefAutoPlay">悬停自动播放（音频、视频和效果预览）').replace('id="prefMuted">视频默认静音</label>','id="prefMuted">视频默认静音</label><label><input type="checkbox" id="prefAudioMuted">音频默认静音</label>').replace('中文图文模型，首次下载约 191 MB。图片在本机分析。AI 标签会追加到所选素材，可在资料栏修改。','在本机按画面内容找素材。首次需下载约 191 MB 模型；分析图片或素材封面，不识别整段视频、语音或工程图层。').replace('<label>自动标签候选','<ol class="ai-help"><li>先建立语义索引，再将顶部搜索切到“AI 语义”，输入“海边夕阳”等画面描述。</li><li>以图搜图：选一张参考图片，在已索引素材中找相近画面。</li><li>追加标签：先选素材，从下面的候选词中匹配最多 3 个标签；可在资料栏修改。</li></ol><label>自动标签候选'));
edit('src/renderer.js',s=>{
 s=s.replace("effectsOnly:true,visualIds:","effectsOnly:state.typeShortcut!=='ae',extensions:({pr:['prproj','mogrt','prfpset'],ae:['aep','aepx','ffx'],ps:['psd','psb']})[state.typeShortcut],visualIds:");
 s=s.replace("f.q=$('searchMode')", "if(state.typeShortcut==='audio')f.kind='audio';f.q=$('searchMode')");
 s=s.replace("$('location').textContent=state.recent?", "document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===state.typeShortcut);b.setAttribute('aria-pressed',String(b.dataset.type===state.typeShortcut));});$('allItems').classList.toggle('active',!state.typeShortcut&&!state.folder&&!state.collection&&!state.unclassified&&!state.trash&&!state.favorite&&!state.recent);$('location').textContent=state.typeShortcut?({pr:'Premiere · 工程与模板',ae:'After Effects · 工程与预设',ps:'Photoshop · PSD / PSB',audio:'音频 / 声音'})[state.typeShortcut]:state.recent?");
 s=s.replace('function reset(){','function reset(){state.typeShortcut=null;');
 s=s.replace("for(const id of ['reset','all','allItems'])", "for(const button of document.querySelectorAll('[data-type]'))button.onclick=()=>run(async()=>{await reset();state.typeShortcut=button.dataset.type;await refresh();});\nfor(const id of ['reset','all','allItems'])");
 s=s.replaceAll("$('mute').checked",'!!state.preferences.muted');
 s=s.replace("$('mute').onchange=()=>run(()=>quickPreference({muted:!!state.preferences.muted}));",'');
 s=s.replace('muted:\'prefMuted\',','muted:\'prefMuted\',audioMuted:\'prefAudioMuted\',');
 s=s.replace("!!state.preferences.muted=p.muted;$('quickAutoPlay').setAttribute('aria-pressed',String(p.autoPlay));",'');
 s=s.replace("$('quickAutoPlay').onclick=()=>run(async()=>{await appReady;return quickPreference({autoPlay:!state.preferences.autoPlay});});",'');
 s=s.replace("applyPreferences();$('preferencesDialog').close();", "applyPreferences();if(patch.autoPlay===false)for(const card of document.querySelectorAll('.asset'))card.onmouseleave?.();document.querySelectorAll('video,audio').forEach(v=>v.muted=v.tagName==='AUDIO'?!!state.preferences.audioMuted:state.preferences.muted);$('preferencesDialog').close();");
 return s;
});
edit('src/library.cjs',s=>s.replace("    if (f.ext) {", "    if(Array.isArray(f.extensions)&&f.extensions.length){where.push('ext IN (SELECT value FROM json_each(?))');args.push(JSON.stringify(f.extensions));}\n    if (f.ext) {"));
edit('src/style.css',s=>s+'\n/* Built-in type views: filters, never physical folders. */\n.type-shortcut{display:flex;align-items:center;gap:10px}.type-badge{display:inline-flex;align-items:center;justify-content:center;width:27px;height:27px;border-radius:7px;font-size:14px;font-weight:700;flex-shrink:0;background:var(--panel);border:1px solid currentColor}.type-pr,.type-ae{color:#b0a0ed}.type-ps{color:#70b7e2}.type-audio{color:var(--accent)}.ai-help{padding-left:24px;line-height:1.65;color:var(--muted)}\n');
edit('src/main.cjs',s=>s.replace("label:'创建语义索引'","label:'建立画面索引（供 AI 搜索）'").replace("label:'以图搜图'","label:'用参考图片搜索素材…'").replace("label:'查找重复项'","label:'查找内容完全相同的文件'").replace("label:'AI 模型与标签'","label:'本地 AI：用法、模型与标签…'"));
